const s = $('Settings').first().json.fields, t = $('Trigger').first().json;
// Caller-supplied values go into the system prompt: control/bidi characters and newlines become spaces and | (the field separator) becomes /, so a Telegram name cannot forge a context line; ids keep only token characters.
const clean = (v, max) => Array.from(String(v ?? '').replace(/[\u0000-\u001f\u007f-\u009f\u061c\u200b-\u200f\u2028-\u202e\u2066-\u2069\ufeff]/g, ' ').replace(/\|/g, '/').replace(/\s+/g, ' ').trim()).slice(0, max).join('');
const tok = (v, max) => String(v ?? '').replace(/[^\w.:+-]/g, '').slice(0, max);
const services = $('Services').all().map(i => i.json.fields || {}).filter(x => x.service_id);
const now = DateTime.now().setZone(s.timezone);
const block = [
  `business_name: ${s.business_name}`,
  `timezone: ${s.timezone} | now: ${now.toISO({ suppressMilliseconds: true })} | today: ${now.toFormat('cccc, LLL d, yyyy')}`,
  `contact_id: ${tok(t.contact_id, 40)} | channel: ${tok(t.channel, 10)} | client_language: ${tok(t.language, 10) || 'en'} | client_name: ${clean(t.client_name, 60) || '(unknown)'} | client_status: ${tok(t.client_status, 20) || 'new'}`,
  `cancellation policy: free until ${s.cancellation_hours} hours before the appointment`,
  `services (service_id — name — duration — price):`,
  ...services.map(x => `  ${x.service_id} — ${x.name} — ${x.duration_min} min — $${x.price}`)
].join('\n');
return [{ json: { block } }];

const j = $input.first().json;
const out = (j.output || '').toString();
const steps = Array.isArray(j.intermediateSteps) ? j.intermediateSteps : [];
const tools_used = steps.map(s => s.action && s.action.tool).filter(Boolean);
// Positive matches only: an observation is the JSON of the tool's items, e.g. [{"verdict":"FOUND\n..."}]. A tool error ("There was an error: ...") must neither count as a knowledge-base source nor as an escalation.
const kbUsed = steps.some(s => s.action && s.action.tool === 'search_knowledge' && /"verdict"\s*:\s*"FOUND\b/.test(String(s.observation || '')));
const escalated = steps.some(s => s.action && s.action.tool === 'escalate' && /"verdict"\s*:\s*"ESCALATED"/.test(String(s.observation || '')));
const medical = /\b\d+\s?(units?|mg|ml|iu|cc)\b|\b(botulinum|hyaluron\w*|lidocaine|tretinoin|retin-a|hydroquinone|isotretinoin|accutane|semaglutide|ozempic|antibiotic\w*|steroid\w*|dosage|dose)\b/i;
const violation = medical.test(out) && !kbUsed;
return [{ json: { reply: out, violation, escalated, tools_used } }];
